import {ACTIVITY_GROUPS,MODULE_LABELS,makeActivityIndex,findActivities} from './navigation.js';
import {VAULT_KEY,cryptoReady,checkVault,makeVault,unlockVault,sealVault,changeVaultPassword} from './auth.js';
import {TOPICS,QUESTIONS,MODULES,DATES,DESIRE_OPTIONS,PATHS} from './data.js';
import {KEY,fresh,validate,id,now,availableQuestions} from './store.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)], main=$('#main'),modal=$('#modal'),body=$('#modal-body');
const svgPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3zM12 6v15"/>',notes:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',circles:'<ellipse cx="9" cy="12" rx="6" ry="8"/><ellipse cx="15" cy="12" rx="6" ry="8"/>',pause:'<path d="M8 5v14M16 5v14"/>',bridge:'<path d="M3 19V9m18 10V9M3 14c5-10 13-10 18 0M7 10v9m5-11v11m5-9v9M2 19h20"/>',leaf:'<path d="M20 3C7 2 2 8 5 16s17 4 15-13ZM5 20l10-11"/>',balance:'<path d="M12 3v18M5 6h14M7 21h10M5 6l-4 8h8zm14 0-4 8h8z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',diagonal:'<path d="M6 18 18 6M6 6h12v12"/>',chevron:'<path d="m8 10 4 4 4-4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',device:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',edit:'<path d="m15 4 5 5-11 11-6 1 1-6zM13 6l5 5"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8.5 8.5 0 1 0 10 10Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shuffle:'<path d="M3 5h3l12 14h3M3 19h3L18 5h3m-4-3 4 3-4 3m0 8 4 3-4 3"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14c2 3 6 3 8 0M8 8v1m8-1v1"/>',wave:'<path d="M2 12c3-9 6 9 10 0s7 9 10 0"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${svgPaths[n]||svgPaths.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,action,extra='')=>`<button class="text-link" data-action="${action}" ${extra}>${text}${icon('arrow')}</button>`;
const dateString=(s,long=false)=>new Date(s).toLocaleDateString('es-ES',{day:'numeric',month:long?'long':'short',...(long?{year:'numeric'}:{})});
const dayKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const localDate=s=>s?dateString(s+'T12:00:00'): 'Por acordar';
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error()},setItem(){throw Error()},removeItem(){throw Error()}}}
let db=fresh(),saving=false,storageError=null,baseline=null;
let route='hoy',exploreTab='inicio',category='Todos',search='',questionLevel='all',agreementFilter='all',memoryFilter='all',spaceFilter='all',dirty=false,cleanup=null,toastTimer,flow=null,deckState=null;
const name=(i=db.settings.active)=>db.settings.names[i];
function flash(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function commit(message){if(vaultKey&&saving){const snapshot=validate(db);pendingSaves++;saveQueue=saveQueue.then(async()=>{if(storageError)return;try{if(accountStored()!==baseline)throw Error('conflict');const expected=baseline,next=await sealVault(vault,vaultKey,snapshot);const raw=JSON.stringify(next);await writeVault(expected,raw);vault=next;baseline=raw}catch(e){storageError=e.message==='conflict'?'El espacio cambió en otra pestaña. Descarga una copia de tu trabajo antes de recargar. No sobrescribiremos la otra versión.':'No pudimos guardar. Tu trabajo sigue en esta sesión. Descarga una copia cifrada antes de cerrar.';saving=false}}).finally(()=>{pendingSaves--;applySettings();renderNotice()})}applySettings();renderNotice();if(message)flash(message)}
function applySettings(){document.body.dataset.theme=db.settings.theme;document.body.classList.toggle('reduce-motion',db.settings.reduceMotion);$('#storage-label').textContent=pendingSaves?'Guardando…':saving?'Cifrado en este dispositivo':'Solo esta sesión';$('#profile-name').textContent=name();$('#profile-button').setAttribute('aria-label','Cambiar persona. Ahora: '+name());$('#profile-initial').textContent=name().trim().slice(0,1).toUpperCase();$('#today-date').textContent=new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});document.querySelector('meta[name="theme-color"]').content=db.settings.theme==='light'?'#faf6f3':'#18151d'}
function renderNotice(){$('#notice').innerHTML=storageError?`<div class="notice"><p>${esc(storageError)}</p>${link('Gestionar datos','settings')}</div>`:''}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon))}
const navigation=[['hoy','home','Inicio'],['explorar','spark','Actividades'],['nosotros','circles','Nosotros'],['espacio','user','Mi espacio']];
function navigate(v,focus=true,record=true){if(!access||document.body.classList.contains('session-shield'))return;if(!['hoy','explorar','nosotros','acuerdos','recuerdos','espacio'].includes(v))v='hoy';if(modal.open&&!close())return;route=v;if(v==='acuerdos'||v==='recuerdos')coupleTab=v;try{if(record&&location.hash!=='#'+v)history.pushState(null,'','#'+v)}catch{}const current=mainRoute(v);$('#navigation').innerHTML=navigation.map(([r,i,t])=>`<a href="#${r}" ${current===r?'class="active" aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');$('#route-label').textContent=navigation.find(n=>n[0]===current)[2];$('#modal-close-label').textContent='Volver';render();window.scrollTo({top:0,behavior:'instant'});if(focus)main.focus({preventScroll:true})}
function show(label,html){delete modal.dataset.finder;$('#modal-label').textContent=label;body.innerHTML=html;hydrateIcons(body);if(!modal.open)modal.showModal();modal.scrollTop=0;dirty=false;const title=$('#modal-title');if(title){title.tabIndex=-1;title.focus({preventScroll:true})}}
function close(force=false){delete modal.dataset.finder;if(!force&&(dirty||(flow?.type==='exercise'&&!flow.saved&&flow.answers.some(a=>a.trim())))&&!window.confirm('Hay un texto sin guardar. ¿Quieres descartarlo?'))return false;if(cleanup){cleanup();cleanup=null}modal.close();dirty=false;flow=null;deckState=null;return true}
function title(t){return `<h2 id="modal-title">${t}</h2>`}
function steps(n,total){return `<div class="steps" aria-label="Paso ${n} de ${total}">${Array.from({length:total},(_,i)=>`<span class="${i<n?'done':''}"></span>`).join('')}</div>`}
function localHelp(){return `<p class="help">${saving?'Se guardará cifrado en este navegador.':'Solo se conservará durante esta sesión.'} Quien tenga abierto este espacio puede verlo. No se envía a otra persona.</p>`}
function complete(module,helpful=''){db.completed.push({id:id(),module,helpful,created:now()});commit();render()}
function card(m){const done=db.completed.some(c=>c.module===m.id);return `<button class="card" data-action="module" data-id="${m.id}"><span class="card-icon ${m.color}">${icon(m.icon)}</span><h3>${m.title}</h3><p>${m.description}</p><span class="card-bottom"><span>${m.minutes} min${m.adult?' · +18':''}${m.solo?' · Individual':''}</span>${done?icon('check'):icon('diagonal')}</span></button>`}
function week(){const today=new Date(),mon=new Date(today);mon.setDate(today.getDate()-(today.getDay()+6)%7);mon.setHours(0,0,0,0);const used=new Set([...db.completed,...db.checkins,...db.gratitudes].map(c=>dayKey(new Date(c.created))));let count=0;const days=Array.from({length:7},(_,i)=>{let d=new Date(mon);d.setDate(d.getDate()+i);let key=dayKey(d),done=used.has(key);if(done)count++;return `<span class="day ${done?'done':''} ${key===dayKey()?'today':''}"><span>${['L','M','X','J','V','S','D'][i]}</span><b aria-label="${d.toLocaleDateString('es-ES')}: ${done?'momento registrado':'sin actividad registrada'}">${done?icon('check'):d.getDate()}</b></span>`}).join('');return `<section class="soft-panel weekly"><div><h3>${count?'Habéis hecho espacio.':'Vuestro ritmo empieza aquí.'}</h3><p>${count} de ${db.settings.goal} días elegidos esta semana. Descansar también cuenta.</p></div><div class="week-dots">${days}</div></section>`}
function exploreDetail(){const labels={preguntas:'Preguntas',planes:'Planes para dos',recorridos:'Recorridos',ejercicios:'Ejercicios'};const label=labels[exploreTab]||'Actividades';let result=`${navTrail(label)}<h1>${label}</h1><p class="intro">${{preguntas:'Elige un tema o deja que una pregunta os encuentre.',planes:'Ideas para disfrutar fuera de la pantalla.',recorridos:'Pequeños pasos, en el orden que os ayude.',ejercicios:'Un momento para cuidar lo que necesitáis.'}[exploreTab]||''}</p>`;
if(exploreTab==='ejercicios'){let ms=MODULES.filter(m=>(category==='Todos'||m.category===category)&&`${m.title} ${m.description}`.toLowerCase().includes(search.toLowerCase()));result+=`<div class="toolbar"><label class="search" aria-label="Buscar ejercicios">${icon('search')}<input id="search-exercises" type="search" placeholder="¿Qué os apetece cuidar?" value="${esc(search)}"></label></div><div class="filters">${['Todos','Conectar','Reparar','Cuidarme','Intimidad'].map(c=>`<button class="chip ${category===c?'selected':''}" aria-pressed="${category===c}" data-action="category" data-id="${c}">${c}</button>`).join('')}</div><div class="grid module-grid" id="module-results">${ms.length?ms.map(card).join(''):empty('No encontramos ese ejercicio.','Prueba con otra palabra o cambia el filtro.','spark')}</div><p class="inline-help">Ejercicios educativos originales inspirados en los enfoques de pareja del proyecto. No son terapia ni cuestionarios diagnósticos.</p>`}
if(exploreTab==='preguntas'){result+=`<div class="toolbar"><span class="quiet">120 preguntas originales · 12 temas</span><span style="flex:1"></span>${btn(icon('shuffle')+'Sorpréndenos','random-question','secondary')}${btn(icon('star')+'Favoritas ('+db.favorites.length+')','favorite-deck','secondary')}</div><div class="grid">${TOPICS.map(([topic,t,sub,level,qs])=>{let remain=availableQuestions(QUESTIONS,db.seen,{topic,adult:true}).length;return `<button class="card deck-card" data-action="deck" data-id="${topic}"><span class="label">${['','Cotidiano','Personal','Profundo'][level]}${topic==='intimidad'?' · +18':''}</span><span class="deck-number">${String(remain).padStart(2,'0')}<span class="small"> / ${qs.length}</span></span><h3>${t}</h3><p>${sub}</p><span class="card-bottom"><span>${remain?'Sin explorar':'Tema completado'}</span>${icon('diagonal')}</span></button>`}).join('')}</div><p class="inline-help">Las preguntas vistas no se repiten automáticamente. Puedes revisitar un tema o tus favoritas cuando lo elijas. Con una cuenta local, vuestro progreso queda guardado al volver.</p>`}
if(exploreTab==='recorridos')result+=PATHS.map(p=>{const done=p.modules.filter(m=>db.completed.some(c=>c.module===m)).length;return `<button class="path" data-action="path" data-id="${p.id}"><span class="card-icon ${p.color}">${icon(p.icon)}</span><span class="path-info"><h3>${p.title}</h3><p>${p.desc}</p><div class="progress-track" role="progressbar" aria-label="${p.title}" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${p.modules.length}"><span style="width:${done/p.modules.length*100}%"></span></div><span class="small">${done} de ${p.modules.length} momentos explorados</span></span>${icon('arrow')}</button>`}).join('');
if(exploreTab==='planes')result+=`<div class="toolbar"><p class="quiet" style="margin:0;flex:1">Lo importante es haceros sitio.</p>${btn(icon('shuffle')+'Elegir por nosotros','random-date','secondary')}</div><div class="grid">${DATES.map((d,i)=>`<button class="card date-plan" data-action="date" data-id="${i}"><span class="card-icon ${['sand','lavender','sage'][i%3]}">${icon(['sun','moon','heart'][i%3])}</span><h3>${d.title}</h3><p>${d.text}</p><span class="card-bottom"><span>${d.minutes} min · <span class="cost">${d.cost}</span></span>${db.dateSeen.includes(i)?icon('check'):icon('diagonal')}</span></button>`).join('')}</div>`;return result}
function empty(t,p,i='notes',actions=''){return `<div class="empty"><span class="card-icon">${icon(i)}</span><h2>${t}</h2><p>${p}</p>${actions}</div>`}
function agreements(){const list=db.agreements.filter(a=>agreementFilter==='all'||a.status===agreementFilter).slice().reverse();return `<div class="page-heading"><div><h2 class="collection-heading">Nuestros acuerdos</h2><p class="intro">Propuestas concretas y espacio para ajustar.</p></div>${btn(icon('plus')+'Nueva propuesta','agreement')}</div><div class="filters">${[['all','Todos'],['proposed','Por hablar'],['agreed','En marcha'],['reviewed','Revisados']].map(([k,t])=>`<button class="chip ${agreementFilter===k?'selected':''}" data-action="agreement-filter" data-id="${k}">${t}</button>`).join('')}</div>${list.length?list.map(a=>`<article class="record"><div class="record-body"><span class="badge ${a.status==='proposed'?'pending':a.status==='reviewed'?'good':''}">${{proposed:'Propuesta · Por hablar',agreed:'Acordado entre vosotros',reviewed:'Revisión registrada'}[a.status]}</span><h3>${esc(a.action)}</h3><div class="record-meta"><span>${icon('user')} ${esc(a.owner)}</span><span class="${a.status==='agreed'&&a.date&&a.date<=dayKey()?'due':''}">${icon('calendar')} ${localDate(a.date)}</span></div>${a.review?`<p class="record-note">${esc(a.review)}</p>`:''}<div class="actions" style="margin-top:14px">${a.status==='proposed'?btn('Hemos llegado a un acuerdo','accept','secondary',`data-id="${a.id}"`):btn(a.status==='reviewed'?'Actualizar revisión':'Revisar cómo fue','review','secondary',`data-id="${a.id}"`)}</div></div><div class="record-actions"><button class="icon-btn" data-action="edit-agreement" data-id="${a.id}" aria-label="Editar propuesta">${icon('edit')}</button><button class="icon-btn" data-action="delete" data-kind="agreements" data-id="${a.id}" aria-label="Eliminar propuesta">${icon('trash')}</button></div></article>`).join(''):empty('Una intención puede hacerse pequeña.','Prepara una propuesta para hablarla. Solo será un acuerdo cuando ambos lo aceptéis.','notes',btn('Preparar una propuesta','agreement'))}<p class="inline-help">Registrar un acuerdo aquí no avisa a nadie ni demuestra que la otra persona lo haya aceptado. Habladlo antes.</p>`}
function memories(){let list=db.gratitudes.filter(g=>memoryFilter==='all'||g.person===Number(memoryFilter)).slice().reverse();return `<div class="page-heading"><div><h2 class="collection-heading">Nuestros aprecios</h2><p class="intro">Los gestos que os han hecho bien.</p></div>${btn(icon('plus')+'Escribir un aprecio','gratitude')}</div><div class="history-filter">${[['all','Todos'],['0',db.settings.names[0]],['1',db.settings.names[1]]].map(([k,t])=>`<button class="chip ${memoryFilter===k?'selected':''}" data-action="memory-filter" data-id="${k}">${esc(t)}</button>`).join('')}</div>${list.length?`<div class="memory-grid">${list.map(g=>`<article class="gratitude"><span class="label">UN GESTO QUE IMPORTA</span><button class="bookmark" data-action="delete" data-kind="gratitudes" data-id="${g.id}" aria-label="Eliminar aprecio">${icon('trash')}</button><p class="quote">«${esc(g.text)}»</p><div class="record-meta"><span>${esc(name(g.person))}</span><span>${dateString(g.created,true)}</span></div></article>`).join('')}</div>`:empty('Lo cotidiano también merece recordarse.','Piensa en un gesto concreto: qué hizo la otra persona y cómo te ayudó.','heart',btn('Escribir el primero','gratitude'))}<p class="inline-help">Los aprecios guardados son visibles para quien desbloquee este espacio. Escribir uno no lo envía.</p>`}
function render(){main.dataset.route=mainRoute(route);main.innerHTML=({hoy:home,explorar:explore,nosotros:coupleSpace,acuerdos:coupleSpace,recuerdos:coupleSpace,espacio:personal}[route])();main.classList.remove('fade-in');void main.offsetWidth;main.classList.add('fade-in');applySettings();renderNotice()}
function checkinStart(person=db.settings.active){flow={type:'checkin',person,step:0,mood:'',need:'',text:''};checkinRender()}
function checkinRender(){const f=flow;if(f.step===0){show('CHECK-IN · '+name(f.person),`${steps(1,3)}${title('Antes de nada, ¿cómo estás?')}<p>Elige lo que más se acerque. No necesitas justificarlo.</p><div class="options">${[['Con calma','leaf'],['Con ilusión','sun'],['Con cansancio','moon'],['Con tensión','wave'],['Con tristeza','heart'],['No lo sé','circles']].map(([t,i])=>`<button class="option ${f.mood===t?'selected':''}" data-action="check-mood" data-id="${t}">${icon(i)}${t}</button>`).join('')}</div>${localHelp()}`)}else if(f.step===1){show('CHECK-IN · '+name(f.person),`${steps(2,3)}${title('¿Qué te ayudaría ahora?')}<p>Necesitar espacio también es una respuesta.</p><div class="options">${['Que me escuchen','Ayuda práctica','Un poco de cariño','Un rato para mí','Descansar','Aún no lo sé'].map(t=>`<button class="option ${f.need===t?'selected':''}" data-action="check-need" data-id="${t}">${t}</button>`).join('')}</div>${btn('Volver','check-back','ghost')}`)}else show('CHECK-IN · '+name(f.person),`${steps(3,3)}${title('Ponlo en tus palabras.')}<div class="summary-line"><b>Cómo llego</b>${esc(f.mood)}</div><div class="summary-line"><b>Qué me ayudaría</b>${esc(f.need)}</div><label for="check-text">Algo más que quieras decir (opcional)</label><textarea id="check-text" maxlength="4000" placeholder="Hoy tengo la cabeza llena y me vendría bien…">${esc(f.text)}</textarea>${localHelp()}<div class="actions">${btn('Registrar mi check-in','check-save')}${btn('Terminar sin guardar','check-discard','secondary')}${btn('Volver','check-back','ghost')}</div>`)}
function checkinDone(save){const f=flow;if(save){db.checkins.push({id:id(),created:now(),person:f.person,mood:f.mood,need:f.need,text:$('#check-text').value.trim()});commit('Check-in registrado.')}const other=1-f.person;dirty=false;show('UN MOMENTO QUE CUENTA',`<div class="success-symbol">${icon('check')}</div>${title('Ya te has escuchado.')}<p>Puedes decir en voz alta lo que necesitas, o dejarlo aquí. No hace falta resolverlo todo ahora.</p><div class="actions">${btn('Le toca a '+esc(name(other)),'handoff-check','secondary',`data-person="${other}"`)}${btn('Terminar','finish')}</div><p class="help">Por turnos en este dispositivo. Las respuestas registradas se pueden consultar en el historial.</p>`);render()}
function checkHandoff(person){flow=null;show('POR TURNOS',`<div class="handoff"><span class="card-icon lavender">${icon('device')}</span>${title('Un momento para '+esc(name(person))+'.')}<p>Pasa el dispositivo cuando quieras. La siguiente persona puede elegir qué expresar y qué guardar.</p>${btn('Soy '+esc(name(person))+' · Continuar','check-person','',`data-person="${person}"`)}</div>`)}
function adultGate(next){if(db.settings.adult){next();return}show('ESPACIO OPCIONAL · +18',`${title('Con curiosidad. Sin expectativas.')}<p>Este contenido está dirigido a personas adultas. Puedes omitir una pregunta o parar en cualquier momento.</p><label class="check-label"><input type="checkbox" id="adult-check"> Soy mayor de 18 años y quiero abrir este espacio.</label><div class="actions"><button class="button" id="adult-continue">Continuar</button>${btn('Ahora no','finish','secondary')}</div>`);$('#adult-continue').onclick=()=>{if(!$('#adult-check').checked){flash('Confirma tu elección para continuar.');return}db.settings.adult=true;commit();next()}}
function moduleStart(mid){const m=MODULES.find(m=>m.id===mid);if(!m)return;const start=()=>{flow={type:'exercise',module:m.id,person:db.settings.active,step:0,answers:m.steps.map(()=>''),saved:false};if(m.id==='deseo'){show(m.basis,`${title('Dos formas de explorar.')}<p>Podéis conversar con preguntas guiadas o descubrir coincidencias por turnos.</p><div class="path-list"><button class="path-step" data-action="exercise-begin">${icon('book')}<span>Conversación guiada · 6 min</span>${icon('arrow')}</button><button class="path-step" data-action="desire-menu">${icon('circles')}<span>Menú de posibilidades · Por turnos</span>${icon('arrow')}</button></div><p class="help">Una coincidencia nunca equivale a consentimiento para hacer algo.</p>`)}else if(m.together){show(m.basis,`${title('Primero, disponibilidad.')}<p>Este ejercicio es para cuando ambos podéis escuchar sin descalificar. Cualquiera puede parar.</p><div class="actions">${btn('Podemos conversar','exercise-begin')}${btn('Necesito una pausa','pause','secondary')}</div>${link('Hay miedo, amenazas o violencia','safety')}`)}else exerciseRender()};m.adult?adultGate(start):start()}
function exerciseRender(){const f=flow,m=MODULES.find(m=>m.id===f.module),s=m.steps[f.step];show(m.basis,`${steps(f.step+1,m.steps.length)}${title(s.title)}<p class="question-big">${esc(s.question)}</p><label for="exercise-answer">Puedes escribirlo o hablarlo sin guardar</label><textarea id="exercise-answer" maxlength="4000" placeholder="${esc(s.placeholder)}">${esc(f.answers[f.step])}</textarea>${s.tip?`<div class="tip">${esc(s.tip)}</div>`:''}${m.id==='autonomia'?link('Me da miedo decir que no','safety'):''}<div class="actions between">${btn(f.step?'Volver':'Cerrar','exercise-back','ghost')}${btn(f.step===m.steps.length-1?'Ver mi reflexión':'Continuar'+icon('arrow'),'exercise-next')}</div><p class="help">${f.step+1} de ${m.steps.length} · Puedes dejar la respuesta en blanco.</p>`)}
function exerciseSummary(){const f=flow,m=MODULES.find(m=>m.id===f.module);show(m.basis,`${title('Lo que te llevas de aquí.')}<p>Una idea pequeña también puede ser suficiente.</p>${f.answers.some(a=>a.trim())?f.answers.map((a,i)=>a.trim()?`<div class="summary-line"><b>${esc(m.steps[i].title)}</b>${esc(a)}</div>`:'').join(''):'<div class="tip">Has recorrido el ejercicio sin escribir. Hablarlo o pensarlo también cuenta.</div>'}${localHelp()}<div class="actions">${f.answers.some(a=>a.trim())?btn('Guardar reflexión','exercise-save'):''}${btn('Terminar sin guardar textos','exercise-discard','secondary')}${btn('Revisar','exercise-return','ghost')}</div>`)}
function exerciseFinish(save){const f=flow,m=MODULES.find(m=>m.id===f.module);if(save&&!f.saved){db.notes.push({id:id(),created:now(),person:f.person,title:m.title,module:m.id,text:f.answers.map((a,i)=>a.trim()?m.steps[i].title+'\n'+a:'').filter(Boolean).join('\n\n')});f.saved=true;commit('Reflexión guardada.')}dirty=false;show('ANTES DE TERMINAR',`${title('¿Te ha servido este momento?')}<p>Tu respuesta describe tu experiencia. No puntúa la relación ni a la otra persona.</p><div class="options">${['Me ha ayudado','Me ha dejado igual','Me ha incomodado','Prefiero no responder'].map(t=>`<button class="option" data-action="helpful" data-id="${t}" data-module="${m.id}">${t}</button>`).join('')}</div>`);render()}
function exerciseEnd(mid,helpful){complete(mid,helpful);flow=null;show('MOMENTO COMPLETADO',`<div class="success-symbol">${icon('check')}</div>${title(helpful==='Me ha incomodado'?'Puedes darte espacio.':'Llévatelo fuera de la pantalla.')}<p>${helpful==='Me ha incomodado'?'No necesitas seguir explorando hoy. Puedes dejar el ejercicio y buscar apoyo si lo necesitas.':'Si habéis encontrado algo concreto que probar, podéis convertirlo en una propuesta.'}</p><div class="actions">${helpful!=='Me ha incomodado'?btn('Preparar una propuesta','agreement','secondary'):btn('Un momento de calma','pause','secondary')}${btn('Terminar','finish')}</div>`)}
function openDeck(topic='all',favorite=false,revisit=false){const run=()=>{deckState={topic,favorite,revisit,current:null};nextQuestion()};if(topic==='intimidad')adultGate(run);else run()}
function nextQuestion(){const d=deckState;if(!d)return;const candidates=availableQuestions(QUESTIONS,d.revisit?(d.revisitSeen||[]):db.seen,{topic:d.topic,adult:db.settings.adult,favorites:d.favorite?db.favorites:null,level:questionLevel});if(!candidates.length){show('PREGUNTAS A VUESTRO RITMO',`${title(d.favorite?'Aquí no hay más favoritas.':'Has explorado este espacio.')}<p>${d.favorite?'Guarda preguntas con la estrella para volver a ellas.':'No repetiremos preguntas sin que lo elijáis. Podéis cambiar de tema o volver a mirar estas con otros ojos.'}</p><div class="actions">${!d.favorite?btn('Volver a este tema','revisit-deck','secondary'):''}${btn('Elegir otro tema','close-to-questions')}</div>`);return}const q=candidates[Math.floor(Math.random()*candidates.length)];d.current=q;if(d.revisit){d.revisitSeen??=[];d.revisitSeen.push(q.id)}if(!d.revisit&&!db.seen.includes(q.id)){db.seen.push(q.id);commit()}questionRender()}
function questionRender(){const d=deckState,q=d.current,t=TOPICS.find(t=>t[0]===q.topic);show(t[1]+' · '+['','Cotidiano','Personal','Profundo'][q.level],`<div class="question-tools"><span class="badge">${d.revisit?'Revisitar una pregunta':'Intimidad progresiva'}</span><button class="icon-btn ${db.favorites.includes(q.id)?'coral':''}" data-action="favorite" data-id="${q.id}" aria-label="${db.favorites.includes(q.id)?'Quitar de favoritas':'Guardar en favoritas'}" aria-pressed="${db.favorites.includes(q.id)}">${icon('star')}</button></div>${title('Una pregunta. Todo el tiempo.')}<p class="question-big">${esc(q.text)}</p><div class="tip">Responded por turnos. Antes de dar tu respuesta, prueba: «Lo que entiendo es… ¿lo he entendido bien?».</div><p class="help">Podéis omitirla. No hay obligación de contar algo que no queráis compartir.</p><div class="actions">${btn('Otra pregunta'+icon('arrow'),'next-question')}${btn('Responder por turnos','answer-turns','secondary')}${btn('Terminar','question-finish','ghost')}</div>`)}
function startTurns(){const q=deckState.current;flow={type:'turns',q:q.text,qid:q.id,person:0,answers:['','']};turnRender()}
function turnRender(){show('CONVERSACIÓN POR TURNOS',`${title('Tu turno, '+esc(name(flow.person))+'.')}<p class="question-big">${esc(flow.q)}</p><label for="turn-answer">Tu respuesta (opcional)</label><textarea id="turn-answer" maxlength="4000" placeholder="Escribe solo lo que quieras compartir."></textarea><p class="help">Estas respuestas no se guardan. Solo se mostrarán juntas si ambos autorizáis compartirlas.</p><div class="actions">${btn('Quiero compartir mi respuesta','turn-next')}${btn('Prefiero omitir y terminar','turn-discard','secondary')}</div>`)}
function turnNext(){flow.answers[flow.person]=$('#turn-answer').value.trim();dirty=false;if(flow.person===0){flow.person=1;show('POR TURNOS',`<div class="handoff"><span class="card-icon lavender">${icon('device')}</span>${title('Ahora, '+esc(name(1))+'.')}<p>La primera respuesta está oculta mientras escribes la tuya. Esto no es un bloqueo de seguridad del dispositivo.</p>${btn('Estoy preparado/a','turn-ready')}</div>`)}else{flow.shared=true;show('VUESTRAS DOS PERSPECTIVAS',`${title('Escuchar antes de responder.')}<p>${esc(flow.q)}</p>${flow.answers.map((a,i)=>`<div class="summary-line"><b>${esc(name(i))}</b>${esc(a||'Sin respuesta escrita.')}</div>`).join('')}<div class="tip">¿Qué has entendido mejor? No es necesario estar de acuerdo para escuchar.</div><p class="help">Al cerrar se descartan ambas respuestas.</p>${btn('Terminar y descartar respuestas','turn-discard')}`)}}
function gratitude(){show('APRECIO · INSPIRADO EN LOS GOTTMAN',`${title('Un gesto que no pasó desapercibido.')}<p>«He visto que hoy ____. Me ayudó porque ____.»</p><form id="gratitude-form"><label for="gratitude-person">Quién escribe</label><select id="gratitude-person">${db.settings.names.map((n,i)=>`<option value="${i}" ${i===db.settings.active?'selected':''}>${esc(n)}</option>`).join('')}</select><label for="gratitude-text">Lo que quieres agradecer</label><textarea id="gratitude-text" required maxlength="4000" placeholder="Gracias por escucharme antes de intentar resolverlo. Me sentí acompañado."></textarea>${localHelp()}<p class="help">No tiene que recibir otro agradecimiento a cambio.</p><div class="actions"><button class="button" type="submit">Guardar en Recuerdos ${icon('heart')}</button>${btn('Terminar sin guardar','finish','ghost')}</div></form>`);$('#gratitude-form').onsubmit=e=>{e.preventDefault();const text=$('#gratitude-text').value.trim();if(!text){$('#gratitude-text').focus();return}db.gratitudes.push({id:id(),created:now(),person:Number($('#gratitude-person').value),text});commit('Un gesto que queda recogido.');close(true);navigate('recuerdos')}}
function journal(){show('REFLEXIÓN PERSONAL',`${title('Unas líneas para ti.')}<form id="journal-form"><label for="journal-title">Título</label><input id="journal-title" maxlength="150" value="Lo que necesito hoy" required><label for="journal-text">Tu reflexión</label><textarea id="journal-text" maxlength="12000" required placeholder="¿Qué estás sintiendo? ¿Qué necesitas? ¿Qué está en tu mano?"></textarea>${localHelp()}<button class="button" type="submit">Guardar reflexión</button></form>`);$('#journal-form').onsubmit=e=>{e.preventDefault();const text=$('#journal-text').value.trim(),t=$('#journal-title').value.trim();if(!text||!t)return;db.notes.push({id:id(),created:now(),person:db.settings.active,title:t,text,module:'journal'});commit('Reflexión guardada.');close(true);navigate('espacio')}}
function agreementEdit(aid){const a=db.agreements.find(a=>a.id===aid);show(a?'AJUSTAR PROPUESTA':'DEL DECIR AL HACER',`${title('Algo pequeño y concreto.')}<form id="agreement-form"><label for="agreement-action">¿Qué propones hacer?</label><textarea id="agreement-action" required maxlength="500" style="min-height:90px" placeholder="Organizar y hacer la compra esta semana.">${esc(a?.action||'')}</textarea><div class="form-grid"><label for="agreement-owner">¿Quién se haría cargo?<select id="agreement-owner">${[...db.settings.names,'Ambos, por acordar',...(a&&![...db.settings.names,'Ambos, por acordar'].includes(a.owner)?[a.owner]:[])].map(n=>`<option ${a?.owner===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label for="agreement-date">¿Cuándo lo revisaríais?<input type="date" id="agreement-date" value="${esc(a?.date||'')}"></label></div><p class="help">${a?'Si cambias la propuesta, volverá a quedar pendiente de hablar.':'Se registrará como propuesta, hasta que ambos la hayáis aceptado.'}</p>${localHelp()}<div class="actions"><button class="button" type="submit">${a?'Guardar cambios':'Preparar propuesta'}</button>${btn('Cancelar','finish','ghost')}</div></form>`);$('#agreement-form').onsubmit=e=>{e.preventDefault();const action=$('#agreement-action').value.trim();if(!action)return;const fields={action,owner:$('#agreement-owner').value,date:$('#agreement-date').value,status:'proposed',accepted:false};if(a)Object.assign(a,fields);else db.agreements.push({id:id(),created:now(),...fields,review:''});commit('Propuesta lista para hablarla.');close(true);navigate('acuerdos')}}
function acceptAgreement(aid){const a=db.agreements.find(a=>a.id===aid);if(!a)return;show('DECISIÓN COMPARTIDA',`${title('¿Lo habéis hablado?')}<p>${esc(a.action)}</p><label class="check-label"><input type="checkbox" id="accept-check"> Ambos hemos podido opinar y hemos aceptado esta propuesta libremente.</label><p class="help">No se enviará una solicitud ni una notificación. Este registro lo completáis vosotros en el dispositivo.</p><div class="actions"><button class="button" id="accept-save">Registrar como acordado</button>${btn('Todavía no','finish','secondary')}</div>`);$('#accept-save').onclick=()=>{if(!$('#accept-check').checked){flash('Confirma que lo habéis hablado y aceptado.');return}a.status='agreed';a.accepted=true;commit('Acuerdo registrado.');close(true);render()}}
function reviewAgreement(aid){const a=db.agreements.find(a=>a.id===aid);if(!a)return;show('REVISAR, SIN PUNTUAR',`${title('¿Cómo os ha sentado?')}<p>${esc(a.action)}</p><form id="review-form"><label for="review-text">¿Qué ayudó y qué necesita ajustarse?</label><textarea id="review-text" required maxlength="4000" placeholder="Podéis tener experiencias diferentes. Recogedlas con vuestras palabras.">${esc(a.review)}</textarea><p class="help">Una revisión no significa que esté todo resuelto. Podéis cambiar la propuesta y volver a hablarla.</p><button class="button" type="submit">Registrar revisión</button></form>`);$('#review-form').onsubmit=e=>{e.preventDefault();const text=$('#review-text').value.trim();if(!text)return;a.review=text;a.status='reviewed';commit('Revisión registrada.');close(true);render()}}
function deleteRecord(kind,rid){if(!['notes','checkins','agreements','gratitudes'].includes(kind))return;show('CONTROL DE TUS DATOS',`${title('¿Eliminar este registro?')}<p>Desaparecerá de este dispositivo y no podrás deshacerlo. Una copia que hayas exportado antes no se modifica.</p><div class="actions"><button class="button danger" id="confirm-delete">Eliminar registro</button>${btn('Cancelar','finish','secondary')}</div>`);$('#confirm-delete').onclick=()=>{db[kind]=db[kind].filter(r=>r.id!==rid);commit('Registro eliminado de este espacio.');close(true);render()}}
function pathOpen(pid){const p=PATHS.find(p=>p.id===pid);if(!p)return;show('UN RECORRIDO A VUESTRO RITMO',`${title(p.title)}<p>${p.desc} No hace falta hacerlos todos hoy.</p><div class="path-list">${p.modules.map((mid,i)=>{const m=MODULES.find(m=>m.id===mid),done=db.completed.some(c=>c.module===mid);return `<button class="path-step" data-action="module" data-id="${m.id}"><b>${i+1}</b><span>${m.title}<br><small class="quiet">${m.minutes} minutos</small></span>${icon(done?'check':'arrow')}</button>`}).join('')}</div><p class="help">Puedes repetir los ejercicios cuando quieras. El progreso indica práctica, no la salud de vuestra relación.</p>`)}
function dateOpen(index){const d=DATES[index];if(!d)return;show('UN PLAN FUERA DE LA PANTALLA',`${title(d.title)}<span class="badge">${d.minutes} min · ${d.cost}</span><p style="margin-top:23px">${d.text}</p><div class="tip">Al terminar: ${d.question}</div><div class="actions">${btn(db.dateSeen.includes(index)?'Lo hemos vuelto a hacer':'Lo hemos hecho','date-done','',`data-id="${index}"`)}${btn('Otra idea','random-date','secondary')}</div><p class="help">Hacedlo solo si os apetece a ambos. Puedes cerrar la app y volver después.</p>`)}
function desireMenu(){flow={type:'desire',person:0,choices:[{},{}],allow:[false,false]};desireRender()}
function desireRender(){show('MENÚ DE POSIBILIDADES · +18',`${title('¿Qué te apetece explorar, '+esc(name(flow.person))+'?')}<p>Elige con libertad. Solo se mostrarán las coincidencias «Me interesa» que ambos autoricéis. «Quizá» no cuenta como un sí.</p>${DESIRE_OPTIONS.map((t,i)=>`<div class="desire-row"><p>${t}</p><div class="filters">${[['yes','Me interesa'],['maybe','Quizá'],['no','No'],['skip','Omitir']].map(([v,l])=>`<button class="chip ${flow.choices[flow.person][i]===v?'selected':''}" data-action="desire-choice" data-index="${i}" data-id="${v}" aria-pressed="${flow.choices[flow.person][i]===v}">${l}</button>`).join('')}</div></div>`).join('')}<label class="check-label"><input type="checkbox" id="desire-consent"> Autorizo mostrar las coincidencias de mis opciones «Me interesa» con las de la otra persona.</label><p class="help">Las opciones no se guardan ni se exportan. Cerrar las descarta. No son un consentimiento para realizar una actividad.</p><div class="actions">${btn(flow.person===0?'Dejar paso a la otra persona':'Ver nuestras coincidencias','desire-next')}${btn('Terminar sin compartir','desire-discard','secondary')}</div>`)}
function desireNext(){if(!$('#desire-consent').checked){flash('Puedes autorizar las coincidencias o terminar sin compartir.');return}flow.allow[flow.person]=true;dirty=false;if(flow.person===0){flow.person=1;show('POR TURNOS',`<div class="handoff"><span class="card-icon lavender">${icon('device')}</span>${title('Tu espacio, '+esc(name(1))+'.')}<p>Las opciones de la otra persona están ocultas. Elige sin intentar adivinarlas.</p>${btn('Elegir mis posibilidades','desire-ready')}</div>`)}else{flow.shared=true;const matches=DESIRE_OPTIONS.filter((_,i)=>flow.choices[0][i]==='yes'&&flow.choices[1][i]==='yes');show('POSIBILIDADES PARA CONVERSAR',`${title(matches.length?'Aquí hay curiosidad compartida.':'Hoy podéis querer cosas diferentes.')}<p>${matches.length?'Estas son las opciones que ambos habéis marcado y autorizado compartir.':'No hay coincidencias «Me interesa». No significa falta de amor ni un problema que haya que resolver.'}</p>${matches.map(t=>`<div class="summary-line">${icon('spark')} ${t}</div>`).join('')}<div class="tip">Preguntad de nuevo antes de hacer cualquier cosa. Podéis decir que no o cambiar de opinión en cualquier momento.</div><div class="actions">${btn('Terminar y descartar opciones','desire-discard')}</div>`);flow.choices=[{},{}]}}
function pause(){if(cleanup)cleanup();flow=null;let remaining=1200,end=null,interval=null;show('BAJAR EL RITMO',`${title('No hay que resolverlo ahora.')}<p>Apoya los pies y suelta los hombros. Respira a un ritmo cómodo; no tienes que seguir una pauta.</p><div class="breath-ring" id="breath-ring">${icon('leaf')}</div><div class="timer-display" id="timer-display" aria-label="Tiempo restante">20:00</div><div class="filters" style="justify-content:center">${[5,10,20,30].map(n=>`<button class="chip ${n===20?'selected':''}" data-minutes="${n}">${n} min</button>`).join('')}</div><div class="actions" style="justify-content:center"><button class="button" id="timer-toggle">Iniciar pausa</button><button class="button secondary" id="timer-reset">Reiniciar</button></div><p class="help">El tiempo es orientativo. Comprobad después si podéis retomar la conversación. No se envía ningún aviso y cerrar la ventana detiene el temporizador.</p>${link('Necesito apoyo, no una conversación conjunta','safety')}`);const update=()=>{const s=end?Math.max(0,Math.ceil((end-Date.now())/1000)):remaining;$('#timer-display').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(end&&s===0){clearInterval(interval);interval=null;end=null;remaining=0;$('#timer-toggle').textContent='Volver a empezar';$('#breath-ring').classList.remove('running');$('#timer-display').textContent='A tu ritmo';flash('Puedes darte más tiempo si lo necesitas.')}};$('#timer-toggle').onclick=()=>{if(end){remaining=Math.max(0,Math.ceil((end-Date.now())/1000));end=null;clearInterval(interval);interval=null;$('#timer-toggle').textContent='Continuar';$('#breath-ring').classList.remove('running')}else{if(!remaining)remaining=1200;end=Date.now()+remaining*1000;interval=setInterval(update,500);$('#timer-toggle').textContent='Pausar';$('#breath-ring').classList.add('running')}update()};$('#timer-reset').onclick=()=>{clearInterval(interval);end=null;remaining=1200;$('#timer-toggle').textContent='Iniciar pausa';$('#breath-ring').classList.remove('running');body.querySelectorAll('[data-minutes]').forEach(b=>b.classList.toggle('selected',b.dataset.minutes==='20'));update()};body.querySelectorAll('[data-minutes]').forEach(b=>b.onclick=()=>{clearInterval(interval);end=null;remaining=Number(b.dataset.minutes)*60;$('#timer-toggle').textContent='Iniciar pausa';$('#breath-ring').classList.remove('running');body.querySelectorAll('[data-minutes]').forEach(x=>x.classList.toggle('selected',x===b));update()});cleanup=()=>{clearInterval(interval)}}
function safety(){if(cleanup){cleanup();cleanup=null}flow=null;show('TU BIENESTAR PRIMERO',`${title('Puedes parar aquí.')}<p>Si hay miedo, amenazas, coacción o violencia, este no es el momento para un ejercicio conjunto. No tienes que compartir estas respuestas ni negociar tu seguridad.</p><div class="tip">Busca apoyo individual de alguien de confianza o de un profesional. Si existe peligro inmediato, contacta con los servicios de emergencia de tu zona.</div><p class="help">ENTRE no detecta emergencias ni avisa a nadie. Cerrar este espacio no borra el historial del navegador.</p><div class="actions">${btn('Cerrar este espacio','safe-close')}${btn('Gestionar lo guardado','settings','secondary')}</div>`)}
function switchPerson(){show('UN MISMO DISPOSITIVO',`${title('¿Quién está usando ENTRE?')}<p>Esto organiza el historial por persona. No hay separación privada entre estos nombres; la contraseña abre el espacio de ambos.</p><div class="options">${db.settings.names.map((n,i)=>`<button class="option ${db.settings.active===i?'selected':''}" data-action="person" data-id="${i}">${icon('user')}${esc(n)}</button>`).join('')}</div>${link('Cambiar nombres y ritmo','setup')}`)}
function download(content,filename){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function about(){show('ENTRE · VERSIÓN LOCAL',`${title('Cerca, sin dejar de ser tú.')}<p>Un espacio educativo para expresar necesidades, escucharos y convertir pequeñas intenciones en acuerdos.</p><h3>Qué funciona aquí</h3><p>120 preguntas originales, ejercicios guiados, conversación por turnos, aprecios, acuerdos y revisiones, planes y un historial que puedes guardar en este dispositivo.</p><h3>Qué significa «local»</h3><p>La cuenta local guarda el espacio cifrado en este navegador. No hay IA conectada ni sincronización. Los nombres organizan los registros; cualquier persona que abra el espacio puede verlos. Puedes explorar sin guardar.</p><h3>Fundamentos</h3><p>El contenido se inspira en los trabajos de John y Julie Gottman, Sue Johnson, Esther Perel, Harville Hendrix y Helen LaKelly Hunt, Arthur Aron, Terrence Real y Silvia Congost. Es contenido original, no una reproducción de sus programas ni un producto avalado por ellos.</p><p>Esta adaptación no ha sido validada clínicamente. No diagnostica, mide cuánto os queréis ni sustituye la terapia. Ante miedo, coacción o violencia, prioriza apoyo individual.</p><ul class="sources"><li><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://www.gottman.com/blog/the-four-horsemen-the-antidotes/">Gottman: comunicación y antídotos</a></li><li><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://iceeft.com/what-is-eft/">ICEEFT: terapia focalizada en las emociones</a></li><li><a class="source-link" target="_blank" rel="noopener noreferrer" href="https://doi.org/10.1177/0146167297234003">Aron et al.: intimidad progresiva (1997)</a></li></ul>${btn('Volver a mi espacio','finish')}`)}
// Account UI shares the app's dialog, typography and local data model.
let vault=null,vaultKey=null,access=false,pendingSaves=0,saveQueue=Promise.resolve(),authBusy=false,authStep=0;
const authRoot=$('#auth-root');
function accountStored(){try{return storage.getItem(VAULT_KEY)}catch{return null}}
async function writeVault(expected,next){const write=()=>{if(storage.getItem(VAULT_KEY)!==expected)throw Error('conflict');if(next===null)storage.removeItem(VAULT_KEY);else storage.setItem(VAULT_KEY,next)};if(globalThis.navigator?.locks)return navigator.locks.request(VAULT_KEY,write);return write()}
function legacyStored(){try{return storage.getItem(KEY)}catch{return null}}
function authPage(heading,copy,content,back=''){document.body.classList.add('locked');$('.sidebar').inert=true;$('.shell').inert=true;authRoot.hidden=false;authRoot.innerHTML=`<div class="auth-layout"><section class="auth-story"><span class="brand">entre<span>•</span></span><div class="auth-art" aria-hidden="true"><i></i><i></i><span>un espacio<br>entre los dos.</span></div><p>CERCA, SIN DEJAR DE SER TÚ</p></section><section class="auth-card"><div class="auth-top"><span class="eyebrow">VUESTRO ESPACIO · SOLO AQUÍ</span>${back}</div><h1 tabindex="-1">${heading}</h1><p class="auth-intro">${copy}</p>${content}<p id="auth-error" class="error" role="alert" aria-live="assertive"></p><div class="auth-footer">${btn('Privacidad','privacy','ghost')}<span>Sin anuncios. Sin una nota para vuestro amor.</span></div></section></div>`;authRoot.querySelector('h1').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function authError(message){const el=$('#auth-error');if(el){el.textContent=message;el.scrollIntoView?.({block:'nearest'});}}
async function authTask(fn){if(authBusy)return;authBusy=true;authRoot.setAttribute('aria-busy','true');const controls=[...authRoot.querySelectorAll('button,input')];controls.forEach(b=>b.disabled=true);const status=$('#auth-error');if(status)status.textContent='Un momento. Estamos abriendo un lugar para vosotros…';try{await fn()}catch(e){authError(e.userMessage||'No se ha podido completar. Tus datos anteriores siguen intactos. Inténtalo de nuevo.')}finally{authBusy=false;authRoot.removeAttribute('aria-busy');controls.forEach(b=>b.disabled=false)}}
function onboarding(step=0){authStep=step;const slides=[['Un momento<br>para <em>vosotros.</em>','Dos minutos para contar cómo llegas. Una pregunta para escucharos. Un acuerdo pequeño que sí podáis cuidar.','2 minutos pueden abrir una conversación.','sun'],['Aquí no hay<br>una <em>nota.</em>','No evaluamos cuánto os queréis. Podéis responder, pasar o parar. ENTRE es un espacio educativo: no es terapia ni un diagnóstico.','Vuestro ritmo también incluye descansar.','leaf'],['Lo vuestro,<br><em>se queda aquí.</em>','Con una cuenta local, nombres, textos y progreso se guardan cifrados en este navegador. No enviamos vuestras respuestas a nadie.','Una contraseña abre el espacio compartido. No separa los datos de cada persona. Si borras los datos del navegador, necesitarás una copia para recuperarlos.','lock']];if(step>=3){authLanding();return}const [h,p,n,i]=slides[step];authPage(h,p,`<div class="auth-note">${icon(i)}<p>${n}</p></div><div class="auth-progress" aria-label="Paso ${step+1} de 4">${[0,1,2,3].map(x=>`<span class="${x===step?'active':''}"></span>`).join('')}</div><div class="actions">${btn(step===2?'Preparar nuestro espacio':'Continuar','on-next')}${step?btn('Atrás','on-back','ghost'):''}</div>`,btn('Saltar','auth-start','ghost'));}
function authLanding(){authPage('Hacedlo <em>vuestro.</em>','Una cuenta local. Un espacio compartido. Sin correo, teléfono ni redes sociales.',`<div class="auth-choices">${btn(accountStored()?'Entrar en este dispositivo':'Crear nuestro espacio',accountStored()?'auth-login':'auth-register')}${accountStored()?'':btn('Ya tengo un espacio','auth-existing','secondary')}${btn('Restaurar una copia','auth-restore','secondary')}${btn('Explorar sin guardar','auth-guest','ghost')}</div><p class="help">No hay sincronización ni invitaciones a otro móvil. Puedes trasladar el espacio con una copia cifrada.</p>`,btn('Ver bienvenida','on-first','ghost'));}
function passwordInput(id,label,confirmation=false){return `<label for="${id}">${label}</label><div class="password-field"><input type="password" id="${id}" required minlength="12" maxlength="200" autocomplete="${confirmation?'new-password':'current-password'}" aria-describedby="password-help"><button type="button" class="text-link" data-action="show-password" data-id="${id}" aria-label="Mostrar ${label.toLowerCase()}" aria-pressed="false">Ver</button></div>`;}
function loginPage(){if(!cryptoReady()){authPage('Necesitamos abrirlo<br><em>con cuidado.</em>','Este navegador no permite el cifrado necesario. Abre ENTRE con un navegador actualizado; tus datos guardados siguen aquí.',btn('Explorar sin guardar','auth-guest','secondary'),btn('Volver','auth-start','ghost'));return}if(!accountStored()){authPage('Tu espacio,<br><em>contigo.</em>','No hay una cuenta local guardada en este navegador. Si la creaste en otro dispositivo, necesitarás la copia que descargaste.',`<div class="auth-choices">${btn('Restaurar una copia','auth-restore')}${btn('Crear un espacio aquí','auth-register','secondary')}</div>`,btn('Volver','auth-start','ghost'));return}authPage('Qué bien<br><em>tenerte aquí.</em>','Introduce la contraseña de vuestro espacio. No se envía a ningún servidor.',`<form id="login-form">${passwordInput('login-password','Contraseña')}<p id="password-help" class="help">Esta cuenta solo existe en este navegador.</p><button type="submit" class="button auth-submit">Entrar ${icon('arrow')}</button></form>${btn('He olvidado la contraseña','auth-recover','ghost')}<div class="auth-divider"></div>${btn('Restaurar una copia','auth-restore','secondary')}`,btn('Volver','auth-start','ghost'));$('#login-form').onsubmit=e=>{e.preventDefault();const password=$('#login-password').value;authTask(async()=>{const raw=accountStored();try{const v=checkVault(JSON.parse(raw)),opened=await unlockVault(v,password);enterAccount(v,opened.key,validate(opened.data),raw)}catch{throw {userMessage:'No hemos podido abrir el espacio. Revisa la contraseña. Si has guardado una clave de recuperación, puedes usarla.'}}})};}
function registerPage(){if(accountStored()){loginPage();return}const legacy=legacyStored();authPage('Un lugar<br><em>para los dos.</em>','Usad nombres o apodos. La contraseña protege el espacio completo; no crea perfiles privados.',`<form id="register-form"><div class="form-grid"><label for="register-one">Tu nombre o apodo<input id="register-one" required maxlength="35" autocomplete="off" placeholder="Cómo te llamamos"></label><label for="register-two">La otra persona <span class="small">(opcional)</span><input id="register-two" maxlength="35" autocomplete="off" placeholder="Puedes añadirlo después"></label></div>${passwordInput('register-password','Crea una contraseña',true)}${passwordInput('register-confirm','Repite la contraseña',true)}<p id="password-help" class="help">Al menos 12 caracteres. Una frase larga que puedas recordar. No reutilices una contraseña de otro servicio.</p>${legacy?'<div class="auth-note"><p>Encontramos datos de la versión anterior. Se incorporarán y se cifrarán al crear la cuenta. Si no podemos leerlos, no los borraremos.</p></div>':''}<label class="check-label"><input type="checkbox" id="register-consent" required> Quiero guardar este espacio cifrado en este navegador. Sé que cualquiera que lo desbloquee podrá ver los registros de ambas personas.</label><button class="button auth-submit" type="submit">Crear espacio local ${icon('arrow')}</button></form>`,btn('Volver','auth-start','ghost'));$('#register-form').onsubmit=e=>{e.preventDefault();if(!cryptoReady()){authError('Este navegador no permite el cifrado necesario. Abre ENTRE con un navegador actualizado. Puedes explorar sin guardar.');return}const password=$('#register-password').value;if(password.length<12||password.length>200){authError('Usa una contraseña de entre 12 y 200 caracteres.');return}if(password!==$('#register-confirm').value){authError('Las contraseñas no coinciden. Vuelve a escribir la segunda.');return}const names=[$('#register-one').value.trim(),$('#register-two').value.trim()||'Persona 2'];if(!names[0]||!$('#register-consent').checked)return;authTask(async()=>{let initial;try{initial=legacy?validate(JSON.parse(legacy)):validate(db)}catch{throw {userMessage:'No podemos leer los datos anteriores. No se han borrado. Descarga la copia anterior desde Privacidad para conservarla.'}}initial.settings.names=names;const created=await makeVault(password,initial);recoverySetup(created,initial,legacy)})};}
function recoverySetup(created,initial,legacy){authPage('Una llave<br><em>por si acaso.</em>','Guarda esta clave fuera de ENTRE. Permite recuperar el acceso sin recordar la contraseña. No la compartas con quien no deba abrir el espacio.',`<div class="recovery-code" id="recovery-code">${created.recoveryCode}</div><p class="help">La clave no contiene tus datos. Para recuperar un espacio borrado del navegador también necesitarás una copia cifrada. Nadie puede restablecer el acceso por correo.</p><button class="button secondary" id="download-recovery">Descargar mi clave</button><form id="recovery-confirm-form"><label class="check-label"><input id="recovery-saved" type="checkbox" required> He guardado esta clave en un lugar seguro.</label><button class="button auth-submit" type="submit">Entrar en nuestro espacio ${icon('arrow')}</button></form>`,btn('Cancelar','auth-start','ghost'));$('#download-recovery').onclick=()=>download(JSON.stringify({app:'ENTRE',type:'recovery-key',key:created.recoveryCode,note:'Guarda esta clave separada de tu copia cifrada. Da acceso a tu espacio.'},null,2),'ENTRE-clave-recuperacion.json');$('#recovery-confirm-form').onsubmit=e=>{e.preventDefault();if(!$('#recovery-saved').checked)return;authTask(async()=>{if(accountStored())throw {userMessage:'Ya se ha creado una cuenta en otra pestaña. Vuelve al inicio para entrar.'};if(legacyStored()!==legacy)throw {userMessage:'Los datos anteriores han cambiado. Vuelve al inicio y crea el espacio de nuevo para incluirlos.'};const raw=JSON.stringify(created.vault);await writeVault(null,raw);let legacyLeft=false;if(legacy){try{storage.removeItem(KEY)}catch{legacyLeft=true}}enterAccount(created.vault,created.key,initial,raw);if(legacyLeft){storageError='El espacio está cifrado, pero no pudimos eliminar los datos anteriores sin cifrar. Puedes descargarlos o eliminarlos desde Privacidad.';renderNotice()}flash('Vuestro espacio está preparado. Empezad por cómo llegáis hoy.')})};}
function enterAccount(v,key,data,raw){vault=v;vaultKey=key;db=data;baseline=raw;access=true;saving=true;storageError=null;authRoot.innerHTML='';authRoot.hidden=true;document.body.classList.remove('locked');$('.sidebar').inert=false;$('.shell').inert=false;navigate('hoy');touchSession();}
function enterGuest(){access=true;saving=false;storageError=null;db=fresh();authRoot.hidden=true;authRoot.innerHTML='';document.body.classList.remove('locked');$('.sidebar').inert=false;$('.shell').inert=false;navigate('hoy');flash('Modo sin guardar. Nada de esta sesión se conserva al cerrar.');}
function recoveryPage(){if(!accountStored()){authLanding();return}authPage('Volver<br><em>a entrar.</em>','Usa la clave que guardaste al crear el espacio y elige una nueva contraseña.',`<form id="recover-form"><label for="recover-key">Clave de recuperación</label><textarea id="recover-key" required autocomplete="off" spellcheck="false" maxlength="100" placeholder="8 grupos separados por guiones"></textarea>${passwordInput('recover-password','Nueva contraseña',true)}${passwordInput('recover-confirm','Repite la nueva contraseña',true)}<p id="password-help" class="help">Al menos 12 caracteres. Sin la contraseña ni la clave no podemos descifrar tus datos. Las copias anteriores conservan su contraseña anterior.</p><button type="submit" class="button auth-submit">Recuperar acceso</button></form>`,btn('Volver','auth-login','ghost'));$('#recover-form').onsubmit=e=>{e.preventDefault();const code=$('#recover-key').value,password=$('#recover-password').value;if(password.length<12||password!==$('#recover-confirm').value){authError('Usa al menos 12 caracteres y repite la misma contraseña.');return}authTask(async()=>{const raw=accountStored();let v,opened;try{v=checkVault(JSON.parse(raw));opened=await unlockVault(v,code,true);opened.data=validate(opened.data)}catch{throw {userMessage:'La clave no abre este espacio. Revisa todos los grupos; puede pertenecer a otra copia.'}}const next=await changeVaultPassword(v,opened.key,password);if(accountStored()!==raw)throw Error('conflict');const nextRaw=JSON.stringify(next);await writeVault(raw,nextRaw);enterAccount(next,opened.key,opened.data,nextRaw);flash('Nueva contraseña guardada. Tu clave de recuperación sigue siendo válida.')})};}
let sessionTimer,lastActivity=0;
function touchSession(){if(!access||!vaultKey)return;lastActivity=Date.now();clearTimeout(sessionTimer);sessionTimer=setTimeout(()=>lockAccount(true),10*60*1000);}
async function lockAccount(automatic=false){if(!access||document.body.classList.contains('session-shield'))return;if(!automatic&&!close())return;if(automatic&&(dirty||flow)){// Never discard an unfinished reflection silently.
 document.body.classList.add('session-shield');showSessionShield();return;
}await saveQueue;if(storageError){showSessionShield();return}clearTimeout(sessionTimer);close(true);body.innerHTML='';main.innerHTML='';$('#navigation').innerHTML='';$('#notice').innerHTML='';$('#profile-name').textContent='Tu espacio';$('#profile-initial').textContent='•';$('#toast').textContent='';vaultKey=null;vault=null;db=fresh();access=false;saving=false;baseline=null;document.body.classList.remove('session-shield');loginPage();}
function showSessionShield(){if(!vaultKey)return;document.body.classList.add('session-shield');$('.shell').inert=true;$('.sidebar').inert=true;if(modal.open)modal.close();authRoot.hidden=false;authRoot.innerHTML=`<div class="auth-lock"><span class="brand">entre<span>•</span></span><h1>Vuestro espacio<br>está <em>en pausa.</em></h1><p>Tu trabajo pendiente sigue en esta sesión. Introduce la contraseña para continuar.</p><form id="shield-form">${passwordInput('shield-password','Contraseña')}<p id="password-help" class="help">Se oculta tras 10 minutos sin actividad.</p><button class="button auth-submit" type="submit">Continuar</button></form><p class="error" id="auth-error" role="alert"></p></div>`;$('#shield-form').onsubmit=e=>{e.preventDefault();const p=$('#shield-password').value;authTask(async()=>{try{await unlockVault(vault,p)}catch{throw {userMessage:'Esa contraseña no abre el espacio. Tu trabajo sigue aquí.'}}document.body.classList.remove('session-shield');authRoot.hidden=true;authRoot.innerHTML='';$('.shell').inert=false;$('.sidebar').inert=false;if(body.innerHTML)modal.showModal();touchSession()})};}
function privacy(){show('PRIVACIDAD · VERSIÓN LOCAL',`${title('Lo íntimo merece claridad.')}<h3>Qué se guarda</h3><p>Nombres o apodos, preferencias, respuestas que decidas guardar, check-ins, aprecios, acuerdos y progreso. En modo sin guardar viven solo en la memoria de esta sesión.</p><h3>Dónde y cómo</h3><p>Con cuenta local, el espacio se cifra en este navegador con AES-GCM. La contraseña se usa para abrirlo, no se almacena. No hay servidor de cuentas, sincronización ni recuperación por correo. Se bloquea tras 10 minutos sin actividad; si tienes un texto pendiente, se oculta hasta que vuelvas a introducir la contraseña.</p><h3>Un espacio compartido</h3><p>Los dos nombres son etiquetas. Toda persona que desbloquee el espacio puede ver ambos historiales. El cifrado protege los datos guardados; no protege lo que otra persona pueda ver en una sesión abierta ni un dispositivo comprometido.</p><h3>Qué sale del dispositivo</h3><p>ENTRE no envía tus respuestas, no incluye analítica, anuncios ni IA conectada. Las fuentes están incluidas. La web necesita cargar sus archivos desde el proveedor de alojamiento, que puede gestionar datos técnicos de acceso y el acceso a la web. Los enlaces externos solo se abren si los pulsas. El HTML descargable funciona sin conexión.</p><h3>Copias y borrado</h3><p>Las copias de una cuenta están cifradas. Conserva la contraseña correspondiente o la clave de recuperación. Puedes borrar el espacio desde Ajustes sin contactar a nadie. Esto no elimina copias descargadas. Borrar datos del navegador puede eliminar el espacio; la clave por sí sola no reconstruye los datos.</p>${legacyStored()?`<div class="auth-note"><div><h3>Datos de la versión anterior</h3><p>Aún hay una copia local sin cifrar. Puedes conservar un archivo o eliminarla después de incorporarla a una cuenta.</p>${btn('Descargar copia anterior','legacy-export','secondary')}${btn('Eliminar copia anterior','legacy-delete','danger')}</div></div>`:''}<p class="help">Esta información describe esta versión. La publicación en una tienda requiere además identificar al responsable y disponer de una política pública y datos de contacto.</p>${btn('Entendido','finish')}`)}
function changePassword(){show('ACCESO LOCAL',`${title('Una nueva contraseña.')}<form id="change-password-form">${passwordInput('change-current','Contraseña actual')}${passwordInput('change-new','Nueva contraseña',true)}${passwordInput('change-confirm','Repite la nueva contraseña',true)}<p id="password-help" class="help">Al menos 12 caracteres. Tu clave de recuperación seguirá funcionando. Las copias ya descargadas conservan su contraseña anterior.</p><p id="change-error" role="alert" class="error"></p><button type="submit" class="button">Guardar contraseña</button></form>`);$('#change-password-form').onsubmit=async e=>{e.preventDefault();const p=$('#change-new').value;if(p.length<12||p!==$('#change-confirm').value){$('#change-error').textContent='Usa al menos 12 caracteres y repite la misma contraseña.';return}const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{await saveQueue;if(storageError)throw Error();const expected=baseline,current=vault,key=vaultKey;await unlockVault(current,$('#change-current').value);const next=await changeVaultPassword(current,key,p);if(accountStored()!==expected||baseline!==expected)throw Error();const raw=JSON.stringify(next);await writeVault(expected,raw);vault=next;baseline=raw;settings();flash('Contraseña actualizada. Descarga una nueva copia cifrada.')}catch{$('#change-error').textContent='No pudimos cambiarla. Revisa la contraseña actual y el aviso de guardado.'}finally{button.disabled=false}};}
function startAuth(){access=false;db=fresh();saving=false;accountStored()?loginPage():onboarding();}

function setup(){show('HACEDLO VUESTRO',`${title('Dos nombres. Vuestro ritmo.')}<p>Los nombres organizan vuestro espacio compartido. No crean perfiles privados.</p><form id="setup-form"><div class="form-grid"><label for="person-one">Primera persona<input id="person-one" maxlength="35" required value="${esc(db.settings.names[0])}"></label><label for="person-two">Segunda persona<input id="person-two" maxlength="35" required value="${esc(db.settings.names[1])}"></label></div><label for="goal">Días que os gustaría haceros un momento</label><select id="goal">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${db.settings.goal===n?'selected':''}>${n} ${n===1?'día':'días'} a la semana</option>`).join('')}</select><p class="help">Es una intención flexible. No se pierde progreso por descansar.</p>${localHelp()}<button type="submit" class="button">Guardar preferencias</button></form>`);$('#setup-form').onsubmit=e=>{e.preventDefault();const names=[$('#person-one').value.trim(),$('#person-two').value.trim()];if(names.some(n=>!n))return;db.settings.names=names;db.settings.goal=Number($('#goal').value);commit('Preferencias actualizadas.');close(true);render()};}
function settings(){show('AJUSTES',`${title('Tu espacio, tus decisiones.')}<div class="settings-row"><div><h3>${vaultKey?'Cuenta local compartida':'Modo sin guardar'}</h3><p>${vaultKey?'Datos cifrados en este navegador. Bloqueo tras 10 minutos sin actividad.':'Nada de esta sesión se conserva al cerrar.'}</p></div>${btn(vaultKey?'Cerrar sesión':'Crear cuenta',vaultKey?'auth-lock':'guest-register','secondary')}</div>${!vaultKey?`<div class="settings-row"><div><h3>Terminar esta sesión</h3><p>Se descartará lo que hayas escrito sin guardar.</p></div>${btn('Volver al acceso','guest-exit','secondary')}</div>`:''}${vaultKey?`<div class="settings-row"><div><h3>Contraseña y recuperación</h3><p>Tu clave de recuperación se entregó al crear el espacio. Guárdala separada de las copias.</p></div>${btn('Cambiar contraseña','password-change','secondary')}</div>`:''}<div class="settings-row"><div><h3>Nombres y ritmo</h3><p>${esc(db.settings.names.join(' y '))} · ${db.settings.goal} días por semana</p></div>${btn('Editar','setup','secondary')}</div><div class="settings-row"><div><h3>Apariencia</h3><p>${db.settings.theme==='dark'?'Oscura, cálida e íntima':'Clara y luminosa'}</p></div>${btn(db.settings.theme==='dark'?'Modo claro':'Modo oscuro','theme','secondary')}</div><div class="settings-row"><div><h3>Reducir movimiento</h3><p>Sin transiciones ni animación de calma.</p></div><button class="button secondary" role="switch" aria-checked="${db.settings.reduceMotion}" data-action="motion">${db.settings.reduceMotion?'Activado':'Desactivado'}</button></div><div class="settings-row"><div><h3>Contenido de intimidad +18</h3><p>${db.settings.adult?'Disponible; puedes desactivarlo.':'Se pide confirmación antes de abrirlo.'}</p></div>${btn(db.settings.adult?'Desactivar':'Configurar','adult-setting','secondary')}</div><div class="settings-row"><div><h3>Copia de seguridad</h3><p>${vaultKey?'Cifrada. Incluye todos los textos y el progreso de ambas personas.':'Crea una cuenta para descargar una copia cifrada de esta sesión.'}</p></div>${btn('Descargar',vaultKey?'export':'guest-register','secondary')}</div><div class="settings-row"><div><h3>Restaurar una copia</h3><p>Revisa su contenido antes de sustituir este espacio.</p></div>${btn('Importar','import','secondary')}</div>${storageError?`<div class="storage-prompt"><p>${esc(storageError)}</p>${link('Descargar mi trabajo actual','export')}${link('Recargar la versión guardada','reload')}</div>`:''}<div class="settings-row"><div><h3>Privacidad</h3><p>Qué guardamos, dónde y quién puede verlo.</p></div>${btn('Leer','privacy','secondary')}</div><div class="settings-row"><div><h3>${vaultKey?'Eliminar cuenta local y datos':'Borrar esta sesión'}</h3><p>Elimina nombres, textos y progreso. Las copias descargadas no se borran.</p></div>${btn('Eliminar','reset','danger')}</div><p class="help">Sin sincronización entre dispositivos, IA conectada, anuncios ni envío de respuestas. La web necesita conexión para abrirse; no se ofrece todavía instalación sin conexión.</p>`)}
function storageToggle(){if(vaultKey)settings();else {close(true);registerPage()}}
function exportConfirm(){if(!vaultKey){close(true);registerPage();return}show('COPIA CIFRADA',`${title('Un lugar seguro para lo vuestro.')}<p>Incluye los registros de ambas personas. Necesitarás la contraseña actual o tu clave de recuperación para abrirla. No incluye la clave de recuperación.</p><p class="help">Guárdala separada de la clave. Las copias ya descargadas no cambian si después cambias la contraseña o borras la cuenta.</p><div class="actions"><button class="button" id="export-confirm">Descargar copia cifrada ${icon('download')}</button>${btn('Cancelar','settings','secondary')}</div><p id="export-error" role="alert" class="error"></p>`);$('#export-confirm').onclick=async()=>{const b=$('#export-confirm');b.disabled=true;try{await saveQueue;const backup=await sealVault(vault,vaultKey,validate(db));download(JSON.stringify(backup),`ENTRE-copia-cifrada-${dayKey()}.json`);settings();flash('Copia cifrada preparada para descargar.')}catch{$('#export-error').textContent='No pudimos preparar la copia. Tu trabajo sigue aquí.'}finally{b.disabled=false}};}
async function importFile(file){if(!file)return;if(file.size>5000000){flash('La copia supera el límite de 5 MB.');return}let parsed;try{parsed=JSON.parse(await file.text())}catch{flash('No se puede leer esta copia. No se ha cambiado ningún dato.');return}if(parsed?.format==='ENTRE-encrypted'){try{checkVault(parsed)}catch{flash('La copia cifrada está incompleta o no es compatible. No se ha cambiado ningún dato.');return}show('ABRIR COPIA CIFRADA',`${title('La llave de esta copia.')}<p>Usa la contraseña que tenía el espacio cuando descargaste esta copia.</p><form id="backup-password-form">${passwordInput('backup-password','Contraseña de la copia')}<p id="password-help" class="help">No se envía a nadie. Si usas tu clave de recuperación, elige también una nueva contraseña.</p><label class="check-label"><input type="checkbox" id="backup-use-key"> Usar mi clave de recuperación</label><div id="backup-recovery-fields" hidden><label for="backup-key">Clave de recuperación</label><textarea id="backup-key" maxlength="100" spellcheck="false"></textarea>${passwordInput('backup-new','Nueva contraseña',true)}${passwordInput('backup-confirm','Repite la nueva contraseña',true)}</div><p id="backup-error" role="alert" class="error"></p><button class="button" type="submit">Revisar copia</button></form>`);$('#backup-new').required=false;$('#backup-confirm').required=false;$('#backup-use-key').onchange=e=>{const use=e.target.checked;$('#backup-recovery-fields').hidden=!use;$('#backup-password').required=!use;$('#backup-password').disabled=use;$('#backup-key').required=use;$('#backup-new').required=use;$('#backup-confirm').required=use};$('#backup-password-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;try{const recovery=$('#backup-use-key').checked;if(recovery&&($('#backup-new').value.length<12||$('#backup-new').value!==$('#backup-confirm').value))throw Error();const result=await unlockVault(parsed,recovery?$('#backup-key').value:$('#backup-password').value,recovery);const incoming=validate(result.data);const next=recovery?await changeVaultPassword(parsed,result.key,$('#backup-new').value):parsed;previewImport(incoming,{vault:next,key:result.key});}catch{$('#backup-error').textContent='No pudimos abrirla. Revisa la contraseña o la clave de esta copia y que las nuevas contraseñas coincidan.'}finally{b.disabled=false}};}else{try{previewImport(validate(parsed),null)}catch{flash('No es una copia válida de ENTRE. No se ha cambiado ningún dato.')}}}
function previewImport(incoming,encrypted){const observed=accountStored();show('RESTAURAR COPIA',`${title('Revisa antes de reemplazar.')}<p>De ${esc(incoming.settings.names.join(' y '))}: ${incoming.notes.length} reflexiones, ${incoming.checkins.length} check-ins, ${incoming.gratitudes.length} aprecios y ${incoming.agreements.length} acuerdos.</p><p>${encrypted?'La copia está cifrada.':'Esta copia antigua no está cifrada. Se cifrará al guardarla en una cuenta.'} ${observed||access?'Sustituirá los registros actuales; no se mezclarán. Puedes cancelar para exportarlos primero.':'Se creará un espacio local con estos registros.'}</p><p id="import-error" class="error" role="alert"></p><div class="actions"><button class="button" id="import-confirm">${encrypted||vaultKey?'Restaurar y sustituir':'Crear cuenta con esta copia'}</button>${btn('Cancelar','finish','secondary')}</div>`);$('#import-confirm').onclick=async()=>{const button=$('#import-confirm');button.disabled=true;try{await saveQueue;if(accountStored()!==observed)throw Error();if(vaultKey){if(storageError)throw Error();const next=await sealVault(vault,vaultKey,incoming),raw=JSON.stringify(next);if(accountStored()!==baseline)throw Error();await writeVault(observed,raw);vault=next;baseline=raw;db=incoming;close(true);render();flash('Copia restaurada con la contraseña de tu cuenta actual.')}else if(encrypted){const raw=JSON.stringify(encrypted.vault);await writeVault(observed,raw);close(true);enterAccount(encrypted.vault,encrypted.key,incoming,raw);flash('Espacio restaurado. Guarda una nueva copia tras hacer cambios.')}else{if(observed)throw {userMessage:'Entra en tu cuenta local antes de importar una copia sin cifrar.'};db=incoming;close(true);registerPage()}}catch(e){$('#import-error').textContent=e.userMessage||'No se pudo restaurar. Los datos actuales no se han sustituido. Revisa el guardado o recarga antes de intentarlo de nuevo.'}finally{button.disabled=false}};}
function resetAll(){show('ELIMINAR CUENTA LOCAL Y DATOS',`${title('¿Cerrar este espacio?')}<p>Se eliminarán de este navegador la cuenta local, nombres, textos y progreso de ambas personas. No se borrarán las copias descargadas ni datos en otros navegadores.</p><label for="reset-word">Escribe BORRAR para confirmar</label><input id="reset-word" autocomplete="off" placeholder="BORRAR"><p id="reset-error" class="error" role="alert"></p><div class="actions"><button class="button danger" id="reset-confirm">Eliminar cuenta y datos</button>${btn('Cancelar','settings','secondary')}</div>`);$('#reset-confirm').onclick=async()=>{if($('#reset-word').value!=='BORRAR'){$('#reset-error').textContent='Escribe BORRAR para confirmar.';return}await saveQueue;try{if(vaultKey&&accountStored()!==baseline)throw Error();if(vaultKey){await writeVault(baseline,null);storage.removeItem(KEY)}}catch{$('#reset-error').textContent='No se pudo completar el borrado. Revisa los ajustes de almacenamiento del navegador antes de cerrar.';return}close(true);body.innerHTML='';main.innerHTML='';clearTimeout(sessionTimer);vaultKey=null;vault=null;db=fresh();saving=false;storageError=null;baseline=null;access=false;authLanding();flash('Este espacio se ha borrado de aquí.')}}

const activityIndex=makeActivityIndex(MODULES,TOPICS,DATES,PATHS);
let libraryGroup='Todas',libraryQuery='',coupleTab='acuerdos',finderQuery='';
const mainRoute=v=>['acuerdos','recuerdos','nosotros'].includes(v)?'nosotros':v;
function navTrail(label){return `<div class="page-trail">${btn(icon('arrow')+'Actividades','all-activities','ghost')}<span>/</span><span>${esc(label)}</span></div>`}
function quickTile(title,detail,i,color,action,extra=''){return `<button class="quick-tile" data-action="${action}" ${extra}><span class="quick-icon ${color}">${icon(i)}</span><span><strong>${title}</strong><small>${detail}</small></span>${icon('diagonal')}</button>`}
function home(){const check=db.checkins.filter(c=>c.person===db.settings.active&&dayKey(new Date(c.created))===dayKey()).at(-1),q=availableQuestions(QUESTIONS,db.seen,{adult:false,level:1})[0],due=db.agreements.find(a=>a.status==='agreed'&&a.date&&a.date<=dayKey());return `<div class="home-heading"><div><span class="eyebrow">UN POCO DE TIEMPO, SIN PRISA</span><h1>Hola, <em>${esc(name())}.</em></h1></div>${btn(icon('search')+'Buscar','finder','secondary home-search')}</div>${!vaultKey?`<div class="guest-ribbon"><span>Modo sin guardar</span>${link('Crear cuenta local','guest-register')}</div>`:''}<div class="home-dashboard"><section class="daily-card"><span class="eyebrow">${check?'TU CHECK-IN ESTÁ GUARDADO':'PARA EMPEZAR · 2 MIN'}</span><h2>${check?'Ya te has hecho un momento.':'¿Cómo llegas hoy?'}</h2><p>${check?'Puedes volver a escucharte o elegir algo para compartir.':'Cuenta cómo estás y qué te vendría bien. Una cosa cada vez.'}</p>${btn(check?'Repetir mi check-in':'Contar cómo estoy'+icon('arrow'),'checkin')}<span class="daily-orbits" aria-hidden="true"></span></section><div class="quick-area"><div class="section-heading compact-heading"><h2>¿Qué te apetece hacer?</h2>${link('Ver todo','all-activities')}</div><div class="quick-grid">${quickTile('Preguntas','Conoceros un poco más','book','lavender','questions')}${quickTile('Agradecer','Un gesto que sí viste','heart','coral','gratitude')}${quickTile('Acuerdos','Lo que queréis cuidar','notes','sage','go-agreements')}${quickTile('Una discusión','Hablar y reparar','bridge','coral','repair-hub')}${quickTile('Deseo','Vuestras coincidencias','spark','lavender','desire-direct')}${quickTile('Planes para dos','Fuera de la pantalla','calendar','sage','plans')}</div></div></div><section class="daily-question"><div class="daily-question-top"><span class="eyebrow">UNA PREGUNTA PARA DOS</span>${icon('book')}</div><p>${q?esc(q.text):'¿Qué os gustaría volver a descubrir?'}</p>${link('Abrir pregunta','daily-question')}</section>${due?`<button class="next-step" data-action="review" data-id="${esc(due.id)}"><span class="quick-icon sage">${icon('calendar')}</span><span><strong>Un acuerdo para revisar</strong><small>${esc(due.action)}</small></span>${icon('arrow')}</button>`:''}<div class="home-bottom">${btn(icon('leaf')+'Un momento para mí','go-personal','secondary')}${btn(icon('star')+'Preguntas favoritas','favorite-deck','ghost')}</div><p class="home-footnote">${icon('lock')} ${vaultKey?'Espacio local cifrado.':'Solo durante esta sesión.'} No se envían respuestas ni se puntúa la relación.</p>`}
function activityRow(e){return `<button class="activity-row" data-action="open-activity" data-entry="${esc(e.id)}"><span class="quick-icon ${e.color}">${icon(e.icon)}</span><span class="activity-info"><strong>${esc(e.title)}</strong><span>${esc(e.description)}</span><small>${esc(e.meta)}</small></span>${icon('arrow')}</button>`}
function activityResults(){const searching=!!libraryQuery.trim(),matches=findActivities(activityIndex,libraryQuery,libraryGroup).filter(e=>searching||e.featured);if(!matches.length)return `<div class="empty"><span class="quick-icon lavender">${icon('search')}</span><h2>No lo encontramos con esas palabras.</h2><p>Prueba «acuerdos», «calma», «deseo» o «diario».</p>${btn('Ver todas las actividades','clear-activities','secondary')}</div>`;if(searching)return `<p class="result-count" role="status">${matches.length} ${matches.length===1?'resultado':'resultados'}</p><div class="activity-list">${matches.map(activityRow).join('')}</div>`;return ['Conectar','Reparar','Disfrutar','Cuidarme','Recorridos'].map(g=>{const entries=matches.filter(e=>e.group===g);return entries.length?`<section class="activity-section"><h2>${{Conectar:'Para acercaros',Reparar:'Para hablar y reparar',Disfrutar:'Para disfrutar juntos',Cuidarme:'Para cuidarte',Recorridos:'Con un poco de guía'}[g]}</h2><div class="activity-list">${entries.map(activityRow).join('')}</div></section>`:''}).join('')}
function explore(){if(exploreTab!=='inicio')return exploreDetail();return `<div class="page-heading"><div><h1>Actividades</h1><p class="intro">Encuentra lo que necesitas para este momento.</p></div></div><div class="library-search"><label for="activity-search">${icon('search')}<input id="activity-search" type="search" placeholder="Preguntas, acuerdos, deseo…" value="${esc(libraryQuery)}" autocomplete="off"></label></div><div class="activity-filters" aria-label="Filtrar actividades">${ACTIVITY_GROUPS.map(g=>`<button class="chip ${libraryGroup===g?'selected':''}" aria-pressed="${libraryGroup===g}" data-action="activity-group" data-id="${g}">${g}</button>`).join('')}</div><div id="activity-results">${activityResults()}</div><p class="inline-help">Podéis pasar, parar o hacerlo sin escribir. Los ejercicios son educativos; no diagnostican ni sustituyen la terapia.</p>`}
function coupleSpace(){const tab=route==='recuerdos'?'recuerdos':route==='acuerdos'?'acuerdos':coupleTab;return `<div class="page-heading"><div><span class="eyebrow">${esc(db.settings.names.join(' + '))}</span><h1>Nosotros</h1><p class="intro">Lo que acordáis. Lo que os hace bien.</p></div></div><div class="couple-tabs" role="tablist" aria-label="Nuestro espacio">${[['acuerdos','notes','Acuerdos'],['recuerdos','heart','Aprecios']].map(([k,i,t])=>`<button role="tab" id="tab-${k}" aria-controls="couple-content" aria-selected="${tab===k}" tabindex="${tab===k?0:-1}" data-action="couple-tab" data-id="${k}" class="${tab===k?'selected':''}">${icon(i)}${t}</button>`).join('')}</div><section id="couple-content" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='acuerdos'?agreements():memories()}</section><details class="rhythm-panel"><summary>${icon('calendar')} Nuestro ritmo esta semana</summary>${week()}</details>`}
function personal(){const notes=db.notes.filter(n=>n.person===db.settings.active),checks=db.checkins.filter(n=>n.person===db.settings.active),all=[...notes.map(n=>({...n,type:'notes'})),...checks.map(c=>({...c,type:'checkins',title:'Mi check-in',text:`${c.mood} · ${c.need}${c.text?'\n'+c.text:''}`}))].filter(n=>spaceFilter==='all'||n.type===spaceFilter).sort((a,b)=>b.created.localeCompare(a.created));return `<div class="page-heading"><div><h1>Mi espacio</h1><p class="intro">Contigo también, ${esc(name())}.</p></div>${btn(icon('settings')+'Ajustes','settings','secondary')}</div><div class="personal-actions">${quickTile('Mi diario','Escribir una reflexión','edit','sage','journal')}${quickTile('Mi autonomía','Límites y autoestima','leaf','lavender','module','data-id="autonomia"')}</div><details class="privacy-summary"><summary>${icon('lock')} Quién puede ver lo que guardo</summary><p>Los dos nombres comparten una cuenta. Cualquier persona que desbloquee este espacio puede leer ambos historiales. Puedes hacer los ejercicios sin guardar tus textos.</p>${link('Leer privacidad','privacy')}</details><div class="section-heading"><h2 id="my-history-heading" tabindex="-1">Mis reflexiones y check-ins</h2><span class="quiet">${all.length}</span></div><div class="history-filter">${[['all','Todo'],['notes','Reflexiones'],['checkins','Check-ins']].map(([k,t])=>`<button class="chip ${spaceFilter===k?'selected':''}" aria-pressed="${spaceFilter===k}" data-action="space-filter" data-id="${k}">${t}</button>`).join('')}</div>${all.length?all.map(n=>`<details class="history-entry"><summary><span><strong>${esc(n.title)}</strong><small>${dateString(n.created,true)}</small></span>${icon('chevron')}</summary><div><p>${esc(n.text)}</p>${btn(icon('trash')+'Eliminar registro','delete','ghost',`data-kind="${n.type}" data-id="${n.id}"`)}</div></details>`).join(''):empty('Un espacio que empieza contigo.','Tus reflexiones y check-ins aparecerán aquí cuando decidas guardarlos.','leaf',btn('Escribir una reflexión','journal','secondary'))}<div class="personal-footer">${link('Descargar copia de seguridad','export')}${link('Necesito apoyo individual','safety')}</div>`}
function finder(){if(!access||!close())return;finderQuery='';show('BUSCAR EN ENTRE',`${title('¿Qué estás buscando?')}<label class="finder-input" for="finder-input">${icon('search')}<input id="finder-input" type="search" placeholder="Acuerdos, preguntas, calma…" autocomplete="off"></label><p class="help">Busca actividades y ajustes. No buscamos dentro de vuestros textos.</p><div id="finder-results"></div>`);modal.dataset.finder='true';renderFinder();$('#finder-input').focus()}
function renderFinder(){const list=finderQuery.trim()?findActivities(activityIndex,finderQuery):['questions','agreements','module-reparar','desire-menu','plans','journal','settings'].map(id=>activityIndex.find(e=>e.id===id));$('#finder-results').innerHTML=`<p class="result-count" role="status">${finderQuery.trim()?list.length+' resultados':'Ir directamente a…'}</p><div class="finder-list">${list.map(activityRow).join('')||'<p class="empty-search">No encontramos esa actividad. Prueba con «calma», «diario» o «copias».</p>'}</div>`}
function openActivity(entryId){const e=activityIndex.find(x=>x.id===entryId);if(!e)return;if(!close())return;actions[e.action]({dataset:{id:e.target}})}
function openActivitySection(tab){if(!close())return;exploreTab=tab;libraryQuery='';libraryGroup='Todas';navigate('explorar')}
function repairHub(){if(!close())return;libraryGroup='Reparar';libraryQuery='';exploreTab='inicio';navigate('explorar')}
function appGuide(){show('UN MAPA SENCILLO',`${title('Cada cosa, en su sitio.')}<div class="guide-list"><p>${icon('home')}<span><strong>Inicio</strong>Tu check-in y los accesos más usados.</span></p><p>${icon('spark')}<span><strong>Actividades</strong>Preguntas, ejercicios, deseo, planes y recorridos.</span></p><p>${icon('circles')}<span><strong>Nosotros</strong>Acuerdos y aprecios guardados.</span></p><p>${icon('user')}<span><strong>Mi espacio</strong>Diario, autonomía, historial y ajustes.</span></p></div><p>Busca por lo que necesitas: «calma», «preguntas» o «contraseña». La pausa está siempre arriba.</p>${btn('Buscar algo','finder')}`)}

const actions={
finder,rhythm:()=>show('VUESTRO RITMO',`${title('Lo que habéis cuidado esta semana.')}<p>Cuenta los días en que habéis registrado un momento. No puntúa vuestra relación.</p>${week()}${link('Cambiar nuestro ritmo','setup')}`),'open-activity':b=>openActivity(b.dataset.entry),'app-guide':appGuide,
'all-activities':()=>openActivitySection('inicio'),questions:()=>openActivitySection('preguntas'),
'activity-group':b=>{libraryGroup=b.dataset.id;render();document.querySelector(`[data-action="activity-group"][data-id="${libraryGroup}"]`)?.focus()},
'clear-activities':()=>{libraryGroup='Todas';libraryQuery='';render();$('#activity-search').focus()},
'repair-hub':repairHub,'desire-direct':()=>{if(!close())return;adultGate(desireMenu)},
'go-agreements':()=>navigate('acuerdos'),'go-memories':()=>navigate('recuerdos'),'go-personal':()=>navigate('espacio'),
'couple-tab':b=>{coupleTab=b.dataset.id;navigate(b.dataset.id,false);document.querySelector(`[data-action="couple-tab"][data-id="${coupleTab}"]`).focus()},
'my-history':()=>{navigate('espacio');$('#my-history-heading').scrollIntoView({block:'start'});$('#my-history-heading').focus()},
'on-first':()=>onboarding(), 'on-next':()=>onboarding(authStep+1),'on-back':()=>onboarding(authStep-1),
'auth-start':authLanding,'auth-login':loginPage,'auth-existing':loginPage,'auth-register':registerPage,'auth-recover':recoveryPage,'auth-guest':enterGuest,
'auth-restore':()=>{$('#import-file').value='';$('#import-file').click()},privacy,'password-change':changePassword,'auth-lock':()=>lockAccount(),
'guest-exit':()=>{if(window.confirm('¿Descartar esta sesión sin guardar y volver al acceso?')){close(true);body.innerHTML='';main.innerHTML='';access=false;db=fresh();authLanding()}},
'guest-register':()=>{if(!close())return;if(accountStored()){flash('Ya hay una cuenta aquí. Descarga o descarta tu sesión antes de entrar.');return}access=false;registerPage()},
'show-password':b=>{const input=document.getElementById(b.dataset.id);input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Ver':'Ocultar';b.setAttribute('aria-pressed',String(input.type==='text'));b.setAttribute('aria-label',(input.type==='password'?'Mostrar':'Ocultar')+' contraseña')},
'legacy-export':()=>{const raw=legacyStored();if(raw)download(raw,'ENTRE-copia-anterior-sin-cifrar.json')},
'legacy-delete':()=>{if(window.confirm('Esta copia anterior no está cifrada. ¿La has incorporado a una cuenta o descargado y quieres eliminarla?')){try{storage.removeItem(KEY);privacy()}catch{flash('No pudimos eliminarla. Revisa los ajustes del navegador.')}}},
finish:()=>close(),setup,settings,switch:switchPerson,checkin:()=>checkinStart(),gratitude,journal,agreement:()=>agreementEdit(),pause,safety,about,
explore:()=>openActivitySection('inicio'),plans:()=>openActivitySection('planes'),
'explore-tab':b=>{exploreTab=b.dataset.id;search='';render()},category:b=>{category=b.dataset.id;render()},
module:b=>moduleStart(b.dataset.id),path:b=>pathOpen(b.dataset.id),date:b=>dateOpen(Number(b.dataset.id)),
'date-done':b=>{const i=Number(b.dataset.id);if(!db.dateSeen.includes(i))db.dateSeen.push(i);complete('date-'+i);close(true);flash('Un momento compartido, registrado.');render()},
'random-date':()=>{const candidates=DATES.map((_,i)=>i).filter(i=>!db.dateSeen.includes(i));const pool=candidates.length?candidates:DATES.map((_,i)=>i);dateOpen(pool[Math.floor(Math.random()*pool.length)])},
'check-mood':b=>{flow.mood=b.dataset.id;flow.step=1;checkinRender()},'check-need':b=>{flow.need=b.dataset.id;flow.step=2;checkinRender()},
'check-back':()=>{if(flow.step===2)flow.text=$('#check-text').value;flow.step--;checkinRender()},'check-save':()=>checkinDone(true),'check-discard':()=>checkinDone(false),
'handoff-check':b=>checkHandoff(Number(b.dataset.person)),'check-person':b=>checkinStart(Number(b.dataset.person)),
person:b=>{db.settings.active=Number(b.dataset.id);commit();close(true);render();flash('Ahora usa ENTRE '+name()+'.')},
'exercise-begin':exerciseRender,'exercise-next':()=>{flow.answers[flow.step]=$('#exercise-answer').value;const m=MODULES.find(m=>m.id===flow.module);if(flow.step===m.steps.length-1)exerciseSummary();else{flow.step++;exerciseRender()}},
'exercise-back':()=>{if(flow.step===0){close();return}flow.answers[flow.step]=$('#exercise-answer').value;flow.step--;exerciseRender()},
'exercise-return':exerciseRender,'exercise-save':()=>exerciseFinish(true),'exercise-discard':()=>exerciseFinish(false),helpful:b=>exerciseEnd(b.dataset.module,b.dataset.id),
deck:b=>openDeck(b.dataset.id),'random-question':()=>openDeck(),'daily-question':()=>{const q=availableQuestions(QUESTIONS,db.seen,{adult:false,level:1})[0];if(q){deckState={topic:q.topic,favorite:false,revisit:false,current:q};db.seen.push(q.id);commit();questionRender()}else openDeck('all')},
'favorite-deck':()=>openDeck('all',true,true),'next-question':nextQuestion,'revisit-deck':()=>{deckState.revisit=true;deckState.revisitSeen=[];nextQuestion()},
'close-to-questions':()=>{close(true);exploreTab='preguntas';navigate('explorar')},favorite:b=>{const qid=b.dataset.id;if(db.favorites.includes(qid))db.favorites=db.favorites.filter(i=>i!==qid);else db.favorites.push(qid);commit();questionRender();render()},
'question-finish':()=>{complete('conversation');close(true)},'answer-turns':startTurns,'turn-next':turnNext,'turn-ready':turnRender,'turn-discard':()=>{const shared=flow?.shared;flow=null;close(true);if(shared)complete('conversation');flash('Respuestas descartadas.')},
'desire-menu':desireMenu,'desire-ready':desireRender,'desire-next':desireNext,'desire-discard':()=>{const shared=flow?.shared;flow=null;close(true);if(shared)complete('deseo');flash('Opciones descartadas.')},
'desire-choice':b=>{flow.choices[flow.person][Number(b.dataset.index)]=b.dataset.id;b.closest('.filters').querySelectorAll('button').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})},
'edit-agreement':b=>agreementEdit(b.dataset.id),accept:b=>acceptAgreement(b.dataset.id),review:b=>reviewAgreement(b.dataset.id),delete:b=>deleteRecord(b.dataset.kind,b.dataset.id),
'agreement-filter':b=>{agreementFilter=b.dataset.id;render()},'memory-filter':b=>{memoryFilter=b.dataset.id;render()},'space-filter':b=>{spaceFilter=b.dataset.id;render()},
theme:()=>{db.settings.theme=db.settings.theme==='dark'?'light':'dark';commit();settings();render()},motion:()=>{db.settings.reduceMotion=!db.settings.reduceMotion;commit();settings()},
'adult-setting':()=>{if(db.settings.adult){db.settings.adult=false;commit();settings()}else adultGate(settings)},'storage-toggle':storageToggle,
export:()=>exportConfirm(),'export-raw':()=>exportConfirm(true),import:()=>{$('#import-file').value='';$('#import-file').click()},reset:resetAll,
reload:()=>{if(window.confirm('Los cambios que solo están en esta sesión se perderán. ¿Has descargado una copia y quieres recargar?'))location.reload()},
'clear-broken':()=>{show('COPIA LOCAL ANTERIOR',`${title('¿Descartar la copia local anterior?')}<p>Se elimina la copia guardada que no hemos podido usar. Tus datos actuales seguirán en esta sesión. Puedes descargar ambas copias antes.</p><div class="actions"><button class="button danger" id="clear-broken-confirm">Eliminar copia anterior</button>${btn('Cancelar','settings','secondary')}</div>`);$('#clear-broken-confirm').onclick=()=>{try{storage.removeItem(KEY);baseline=null;storageError=null;saving=false;settings();render()}catch{flash('El navegador no permite borrar esa copia.')}}},
'safe-close':()=>{close(true);navigate('hoy')}
};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&access&&!document.body.classList.contains('session-shield')){e.preventDefault();finder();return}if(e.target.matches('[role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...e.target.closest('[role=tablist]').querySelectorAll('[role=tab]')],i=tabs.indexOf(e.target),n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click()}});
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href^="#"]');if(anchor&&!anchor.classList.contains('skip')){e.preventDefault();navigate(anchor.getAttribute('href').slice(1));return}const b=e.target.closest('button[data-action]');if(!b||b.disabled||authBusy)return;if((!access||document.body.classList.contains('session-shield'))&&!b.closest('#auth-root')&&!b.closest('#modal'))return;const fn=actions[b.dataset.action];if(!fn)return;if(cleanup){cleanup();cleanup=null}try{fn(b)}catch(err){console.error('ENTRE: no se pudo completar la acción',err.name);flash('No se pudo completar la acción. Tu trabajo sigue aquí.')}});
modal.addEventListener('input',e=>{if(e.target.id==='finder-input'){finderQuery=e.target.value;renderFinder();return}dirty=true});modal.addEventListener('cancel',e=>{e.preventDefault();close()});$('#modal-close').onclick=()=>close();
$('#import-file').addEventListener('change',e=>importFile(e.target.files[0]));
main.addEventListener('input',e=>{if(e.target.id==='activity-search'){libraryQuery=e.target.value;$('#activity-results').innerHTML=activityResults();return}if(e.target.id==='search-exercises'){search=e.target.value;const ms=MODULES.filter(m=>(category==='Todos'||m.category===category)&&`${m.title} ${m.description}`.toLowerCase().includes(search.toLowerCase()));$('#module-results').innerHTML=ms.length?ms.map(card).join(''):empty('No encontramos ese ejercicio.','Prueba con otra palabra o cambia el filtro.','search')}});
window.addEventListener('popstate',()=>{if(modal.open&&!close()){try{history.pushState(null,'','#'+route)}catch{};return}navigate(location.hash.slice(1),true,false)});
window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==route)navigate(location.hash.slice(1),true,false)});
window.addEventListener('beforeunload',e=>{if(pendingSaves||dirty||(!saving&&(db.notes.length||db.checkins.length||db.agreements.length||db.gratitudes.length))){e.preventDefault();e.returnValue=''}});
window.addEventListener('storage',e=>{if(e.key===VAULT_KEY&&e.newValue!==baseline&&access&&vaultKey){saving=false;storageError='El espacio cambió en otra pestaña. Descarga tu trabajo antes de recargar. No se sobrescribirá la otra versión.';renderNotice();applySettings()}});
hydrateIcons();startAuth();
for(const event of ['pointerdown','keydown','input'])document.addEventListener(event,()=>{if(!document.body.classList.contains('session-shield'))touchSession()},{passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&vaultKey&&Date.now()-lastActivity>=600000)lockAccount(true)});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_entre_exercise',description:'Abre un ejercicio educativo de ENTRE. No registra ni comparte respuestas.',inputSchema:{type:'object',properties:{exercise:{type:'string',enum:MODULES.map(m=>m.id)}},required:['exercise'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!access||document.body.classList.contains('session-shield'))throw Error('Abre primero tu espacio local');if(!input||!MODULES.some(m=>m.id===input.exercise))throw Error('Ejercicio no válido');moduleStart(input.exercise);return{opened:input.exercise}}})).catch(()=>{});}catch{}}
